using DriveOS.Modules.CurriculumPedagogy.Domain.Curricula;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Configurations;
internal sealed class CurriculumModuleConfiguration:IEntityTypeConfiguration<CurriculumModule>{public void Configure(EntityTypeBuilder<CurriculumModule>b){b.ToTable("curriculum_modules");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new CurriculumModuleId(x)).ValueGeneratedNever();b.Property(x=>x.CurriculumVersionId).HasConversion(x=>x.Value,x=>new CurriculumVersionId(x));b.Property(x=>x.Code).HasMaxLength(40);b.Property(x=>x.Name).HasMaxLength(160);b.Property(x=>x.Description).HasMaxLength(2000);b.HasIndex(x=>new{x.CurriculumVersionId,x.Code}).IsUnique();b.HasIndex(x=>new{x.CurriculumVersionId,x.Order}).IsUnique();b.HasMany(x=>x.Competencies).WithOne().HasForeignKey(x=>x.CurriculumModuleId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Competencies).UsePropertyAccessMode(PropertyAccessMode.Field);}}
internal sealed class CompetencyConfiguration:IEntityTypeConfiguration<Competency>{public void Configure(EntityTypeBuilder<Competency>b){b.ToTable("competencies");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new CompetencyId(x)).ValueGeneratedNever();b.Property(x=>x.CurriculumModuleId).HasConversion(x=>x.Value,x=>new CurriculumModuleId(x));b.Property(x=>x.Code).HasMaxLength(60);b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Description).HasMaxLength(3000);b.Property(x=>x.LearningObjective).HasMaxLength(2000);b.HasIndex(x=>new{x.CurriculumModuleId,x.Code}).IsUnique();b.HasIndex(x=>new{x.CurriculumModuleId,x.Order}).IsUnique();}}
